import{z as o,x as p,o as s,c as B,q as n,j as t,D as E,d as r,s as i,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"无损分解与依赖保持","description":"","frontmatter":{"title":"无损分解与依赖保持","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lossless-dependency-preserving.md","filePath":"cs/lossless-dependency-preserving.md","lastUpdated":1791413859000}'),F={name:"cs/lossless-dependency-preserving.md"};function d(_,a,D,C,c,m){const l=p("Mermaid");return s(),B("div",null,[a[2]||(a[2]=n('<h1 id="无损分解与依赖保持" tabindex="-1">无损分解与依赖保持 <a class="header-anchor" href="#无损分解与依赖保持" aria-label="Permalink to &quot;无损分解与依赖保持&quot;">​</a></h1><div class="epigraph"><p>无损：投影再连接能回到原关系。保持：每条 FD 仍能在某一个分量上检查。两项目标可拆开，BCNF 常常保不住后者。</p><footer>—— 据 Rissanen；Aho, Beeri and Ullman；Bernstein；主干 BCNF/3NF 课的形式补全</footer></div><p><a href="/cs/fd-closure-min-cover">上一课</a>给出闭包与正则覆盖。本课不重写扩张算法。缺口是分解质量：主干 <a href="/cs/bcnf-3nf">BCNF 与 3NF 取舍</a> 已经用自然语言说了无损与保持；进阶给出判定。查询语言的连接这时是「恢复原关系」而不是「用户写了 JOIN」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把 \\(R(U)\\) 拆成 \\(R_1(U_1), R_2(U_2)\\)，\\(U_1 \\cup U_2 = U\\)。无损连接：任何满足 \\(F\\) 的实例 \\(r\\)，\\(r = \\pi_{U_1}(r) \\bowtie \\pi_{U_2}(r)\\)。二元分解有简便条件：\\(U_1 \\cap U_2 \\to U_1\\) 或 \\(U_1 \\cap U_2 \\to U_2\\) 被 \\(F\\) 蕴含（交决定某一侧）。多路分解用 tableau 追赶（chase）：不等价则追赶出矛盾或多出行。</p><p>依赖保持：存在覆盖，使每条 FD 的左右部都落在某一个 \\(U_i\\) 内。否则要先连接再检查 FD，运行时贵，也容易漏检。3NF 合成保证无损且保持；BCNF 分解保证无损，不保证保持。</p><p><span class="marginnote">术语翻译：「无损」就是「信息没丢」——拆出的表按公共列 JOIN 回去，行集合与原表一模一样，一行不多（多出的叫虚假元组）一行不少。「保持」就是「约束没丢」——每条 FD 仍能在某一张表内部单独检查，不必先把两张表连接起来。</span></p><p><span class="marginnote">Aho, Beeri, Ullman 用 tableau 形式化无损。chase 按 FD 把符号行填齐。本课要的是判定条件，不把 chase 的全体依赖类型写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>二元：算交 \\(X = U_1 \\cap U_2\\)，闭包看是否盖住某一侧。多路：从「一行一块分量投影」的 tableau 出发 chase，看是否能合成原行。保持：把 \\(F\\) 限制到各 \\(U_i\\) 再算覆盖并，看是否与 \\(F\\) 等价（用闭包比）。</p><p><span class="marginnote">数字实例：\\(R_1(A,B)\\) 与 \\(R_2(B,C)\\) 的交是 \\(\\{B\\}\\)。若 \\(F\\) 含 \\(B \\to C\\)，交决定了 \\(R_2\\) 一侧，分解无损；若 \\(F\\) 只有 \\(A \\to B\\) 和 \\(C \\to B\\)，\\(B\\) 决定不了任何一侧，就要警惕连接拼出假行。</span></p><p>反例（经典）：两个重叠候选键导致 BCNF 分解丢掉一条跨分量 FD。设计选择回到主干取舍课：容忍冗余（3NF）或容忍跨表检查（BCNF）。</p>',12)),(s(),t(A,null,{default:E(()=>[i(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEC%5B%22%E5%88%86%E8%A7%A3%22%5D%20--%3E%20LJ%5B%22%E6%97%A0%E6%8D%9F%3F%20%E4%BA%A4%E5%86%B3%E5%AE%9A%E4%B8%80%E4%BE%A7%20%2F%20chase%22%5D%0A%20%20DEC%20--%3E%20DP%5B%22%E4%BF%9D%E6%8C%81%3F%20%E5%88%86%E9%87%8F%E5%86%85%E5%8F%AF%E6%A3%80%20FD%22%5D%0A%20%20LJ%20--%3E%20OK%5B%22%E8%BF%9E%E6%8E%A5%E6%81%A2%E5%A4%8D%22%5D%0A%20%20DP%20--%3E%20LOC%5B%22%E5%B1%80%E9%83%A8%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"无损失败：连接制造虚假元组（悬挂元组拼出从未存在的组合），查询会多行。保持失败：合法分解实例可能暂时违反原 \\(F\\)，直到连接才发现——约束若只建在分量上则漏。触发器跨表检查是工程补丁，不是保持性。",-1)),a[5]||(a[5]=e("p",null,"视图可以用连接恢复外模式，但视图更新异常仍在：无损保证读回，不保证写可唯一翻译。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「两张表能 JOIN 就是无损」。任何有公共列的表都能 JOIN，但结果可能比原表多出从未存在的组合（如拼出根本不存在的「员工—项目」配对）；无损要求对一切合法实例，JOIN 结果都恰好等于原表，而不是只看你手上这一份数据。")],-1)),(s(),t(A,null,{default:E(()=>[i(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%88%9D%E5%A7%8B%20tableau%EF%BC%9A%E6%AF%8F%E4%B8%AA%E5%88%86%E9%87%8F%E4%B8%80%E8%A1%8C%22%5D%20--%3E%20F%5B%22%E5%8F%96%E4%B8%80%E6%9D%A1%20FD%20X%E2%86%92Y%22%5D%0A%20%20F%20--%3E%20E%5B%22X%20%E7%AC%A6%E5%8F%B7%E7%9B%B8%E7%AD%89%E7%9A%84%E8%A1%8C%E6%8A%8A%20Y%20%E6%94%B9%E6%88%90%E5%90%8C%E4%B8%80%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20E%20--%3E%20Q%7B%22%E5%87%BA%E7%8E%B0%E5%85%A8%E5%8C%BA%E5%88%86%E7%AC%A6%E5%8F%B7%E7%9A%84%E5%8E%9F%E8%A1%8C%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20LL%5B%22%E5%88%A4%E5%AE%9A%E6%97%A0%E6%8D%9F%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20M%5B%22%E8%BF%98%E6%9C%89%E6%9C%AA%E7%94%A8%E7%9A%84%20FD%3F%22%5D%0A%20%20M%20--%3E%7C%22%E6%9C%89%22%7C%20F%0A%20%20M%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20FAIL%5B%22%E9%9D%9E%E6%97%A0%E6%8D%9F%EF%BC%9A%E4%BC%9A%E5%87%BA%E8%99%9A%E5%81%87%E5%85%83%E7%BB%84%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入多值依赖——下一课 4NF。也不把水平分片（按行切）与投影分解混为一谈；水平切是后课分区与分片。chase 对一般嵌入依赖可不可停，本课不进。</p><p>后课默认：说到分解，先问无损，再问保持。4NF 处理的是独立多值事实，不是又一条 FD。</p><p>两条轴独立：可以无损不保持，也可以（不当分解）保持但有损——后者不可用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无损：连接不制造假行；二元时交决定一侧。</li><li>保持：FD 可在单表上检查；3NF 合成保两条，BCNF 不总保保持。</li><li>多值依赖与 4NF 下一课。</li><li>出处：Rissanen；Aho, Beeri and Ullman；Bernstein。</li></ul>',6))])}const f=o(F,[["render",d]]);export{u as __pageData,f as default};
